          >('gdk_texture_save_to_tiff')
          .asFunction<int Function(ffi.Pointer<ffi.Void>, ffi.Pointer<Utf8>)>();
  bool saveToTiff(String filename) {
    return withNativeString(filename, (nativeFilename) {
      return (_gdkTextureSaveToTiff(
            this.handle,
            nativeFilename.cast<Utf8>(),
          )) !=
